/* CSS PART 1 OF 2 */

/* DESIGN TOKENS */
:root {
  color-scheme: light;
  --ink: #202a2b;
  --ink-soft: #485454;
  --paper: #f7f6f2;
  --white: #ffffff;
  --surface: #eeede7;
  --line: #d9d9d1;
  --orange: #bd653d;
  --orange-dark: #974b2b;
  --orange-light: #e8b18e;
  --forest: #344a43;
  --forest-deep: #263832;
  --font-display: "Barlow Condensed", "Arial Narrow", sans-serif;
  --font-body: "DM Sans", Arial, sans-serif;
  --content-width: 1200px;
  --gutter: clamp(22px, 5vw, 76px);
  --section-space: clamp(76px, 10vw, 132px);
  --radius: 3px;
  --shadow: 0 16px 48px rgba(28, 38, 34, .12);
}

/* RESET */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

::selection {
  background: var(--orange);
  color: var(--white);
}

/* SHARED TYPOGRAPHY */
h1,
h2,
h3,
h4,
p {
  margin-top: 0;
}

h1,
h2,
h3,
h4 {
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 700;
  line-height: .98;
  letter-spacing: -.025em;
}

h1 {
  max-width: 850px;
  margin-bottom: 26px;
  font-size: clamp(54px, 7.5vw, 100px);
  text-transform: uppercase;
}

h2 {
  margin-bottom: 24px;
  font-size: clamp(42px, 5vw, 66px);
  text-transform: uppercase;
}

h3 {
  font-size: clamp(25px, 2.6vw, 34px);
}

p {
  color: var(--ink-soft);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--orange-dark);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .19em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 2px;
  background: var(--orange);
  content: "";
}

.section-intro {
  max-width: 650px;
  margin-bottom: 48px;
}

.section-intro p {
  max-width: 590px;
  font-size: 17px;
  line-height: 1.8;
}

.lead {
  font-size: clamp(18px, 1.7vw, 21px);
  line-height: 1.75;
}

/* SHARED LAYOUT */
.container {
  width: min(calc(100% - var(--gutter) * 2), var(--content-width));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section--light {
  background: var(--paper);
}

.section--dark {
  background: var(--forest-deep);
  color: var(--white);
}

.section--dark h2,
.section--dark h3 {
  color: var(--white);
}

.section--dark p {
  color: rgba(255, 255, 255, .76);
}

.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 48px;
  margin-bottom: 54px;
}

.section-heading .section-intro {
  margin-bottom: 0;
}

/* HEADER AND NAVIGATION */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 42, 43, .09);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 36px;
  width: min(calc(100% - var(--gutter) * 2), 1380px);
  min-height: 88px;
  margin-inline: auto;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.brand-logo {
  width: 62px;
  height: 62px;
  flex: 0 0 auto;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand-name {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 21px;
  font-weight: 800;
  letter-spacing: .015em;
  text-transform: uppercase;
}

.brand-description {
  margin-top: 5px;
  color: #707876;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.main-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(18px, 2.8vw, 38px);
}

.main-nav a:not(.button) {
  position: relative;
  padding-block: 10px;
  color: var(--ink);
  font-size: 12px;
  font-weight: 700;
  transition: color .2s ease;
}

.main-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 3px;
  left: 0;
  height: 2px;
  background: var(--orange);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .2s ease;
}

.main-nav a:not(.button):hover {
  color: var(--orange-dark);
}

.main-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

/* BUTTONS */
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 54px;
  padding: 15px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--orange);
  color: var(--white);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .095em;
  line-height: 1.3;
  text-align: center;
  text-transform: uppercase;
  cursor: pointer;
  transition: background .2s ease, border-color .2s ease, transform .2s ease;
}

.button:hover {
  background: var(--orange-dark);
  transform: translateY(-2px);
}

.button--outline {
  border-color: rgba(255, 255, 255, .75);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--ink);
}

.button--dark {
  background: var(--forest);
}

.button--dark:hover {
  background: var(--forest-deep);
}

.button-arrow {
  font-size: 17px;
  line-height: 1;
}

/* FULL-BLEED HERO */
.hero {
  position: relative;
  display: flex;
  align-items: center;
  min-height: min(760px, calc(100svh - 88px));
  overflow: hidden;
  isolation: isolate;
  background: var(--forest-deep);
  color: var(--white);
}

.hero-media {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(21, 32, 29, .91) 0%, rgba(21, 32, 29, .76) 43%, rgba(21, 32, 29, .28) 100%),
    linear-gradient(0deg, rgba(21, 32, 29, .38), transparent 55%);
  content: "";
}

.hero-content {
  width: min(calc(100% - var(--gutter) * 2), var(--content-width));
  margin-inline: auto;
  padding-block: 115px 125px;
}

.hero .eyebrow {
  color: var(--orange-light);
}

.hero h1 {
  max-width: 790px;
  color: var(--white);
}

.hero-description {
  max-width: 570px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, .88);
  font-size: clamp(17px, 1.6vw, 20px);
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 48px;
  color: rgba(255, 255, 255, .82);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .11em;
  text-transform: uppercase;
}

.hero-note::before {
  width: 34px;
  height: 1px;
  background: var(--orange-light);
  content: "";
}

/* INTRODUCTION / CREDENTIALS */
.intro-section {
  padding-block: var(--section-space);
}

.intro-layout {
  display: grid;
  grid-template-columns: 1fr .85fr;
  align-items: center;
  gap: clamp(55px, 9vw, 130px);
}

.intro-copy {
  max-width: 650px;
}

.intro-copy p {
  font-size: 17px;
  line-height: 1.85;
}

.intro-copy .lead {
  color: var(--ink);
}

.intro-visual {
  position: relative;
  min-height: 390px;
}

.intro-visual img {
  width: 100%;
  height: 460px;
  object-fit: cover;
  object-position: center;
}

.intro-caption {
  position: absolute;
  right: -22px;
  bottom: 25px;
  max-width: 230px;
  padding: 24px 27px;
  background: var(--forest);
  color: var(--white);
  box-shadow: var(--shadow);
}

.intro-caption strong {
  display: block;
  font-family: var(--font-display);
  font-size: 43px;
  line-height: 1;
}

.intro-caption span {
  display: block;
  margin-top: 8px;
  color: rgba(255, 255, 255, .8);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.credential-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  margin-top: 44px;
  border-top: 1px solid var(--line);
}

.credential-item {
  flex: 1 1 140px;
  padding: 22px 20px 0 0;
}

.credential-item strong {
  display: block;
  color: var(--orange-dark);
  font-family: var(--font-display);
  font-size: 29px;
  line-height: 1.1;
}

.credential-item span {
  display: block;
  margin-top: 6px;
  color: var(--ink-soft);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .09em;
  text-transform: uppercase;
}

/* PROJECT GALLERY */
.projects-section {
  padding-block: var(--section-space);
  background: var(--surface);
}

.projects-grid {
  display: grid;
  grid-template-columns: 1.15fr .85fr;
  grid-template-rows: 300px 260px;
  gap: 18px;
}

.project {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background: var(--forest);
}

.project:first-child {
  grid-row: span 2;
}

.project img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}

.project:hover img {
  transform: scale(1.035);
}

.project::after {
  position: absolute;
  inset: 40% 0 0;
  background: linear-gradient(transparent, rgba(20, 29, 26, .76));
  content: "";
  pointer-events: none;
}

.project-caption {
  position: absolute;
  z-index: 1;
  right: 26px;
  bottom: 24px;
  left: 26px;
  color: var(--white);
}

.project-caption span {
  display: block;
  margin-bottom: 8px;
  color: var(--orange-light);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.project-caption h3 {
  margin: 0;
  color: var(--white);
  font-size: clamp(24px, 3vw, 35px);
}

/* WHY CHOOSE JOSH BROOKS */
.why-section {
  padding-block: var(--section-space);
  background: var(--forest-deep);
  color: var(--white);
}

.why-section .eyebrow {
  color: var(--orange-light);
}

.why-section h2 {
  max-width: 720px;
  color: var(--white);
}

.why-layout {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  align-items: start;
  gap: clamp(55px, 9vw, 120px);
}

.why-lead {
  max-width: 460px;
}

.why-lead p {
  font-size: 18px;
  line-height: 1.85;
}

.why-list {
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 1px solid rgba(255, 255, 255, .2);
}

.why-list li {
  display: grid;
  grid-template-columns: 48px 1fr;
  gap: 20px;
  padding: 25px 0;
  border-bottom: 1px solid rgba(255, 255, 255, .2);
}

.why-number {
  color: var(--orange-light);
  font-family: var(--font-display);
  font-size: 27px;
  font-weight: 700;
}

.why-list h3 {
  margin-bottom: 9px;
  color: var(--white);
  font-size: 25px;
}

.why-list p {
  margin-bottom: 0;
  font-size: 14px;
  line-height: 1.8;
}

/* PROJECT APPROACH / SERVICE PRINCIPLES */
.approach-section {
  padding-block: var(--section-space);
}

.approach-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(45px, 8vw, 100px);
  align-items: center;
}

.approach-copy {
  max-width: 570px;
}

.approach-copy p {
  font-size: 16px;
  line-height: 1.85;
}

.approach-panel {
  padding: clamp(30px, 5vw, 58px);
  border-left: 4px solid var(--orange);
  background: var(--surface);
}

.approach-panel h3 {
  margin-bottom: 18px;
}

.approach-panel p:last-child {
  margin-bottom: 0;
}
```

