/* CSS PART 2 OF 2 */

/* CONTACT AND CONVERSION */
.contact-section {
  padding-block: var(--section-space);
  background: var(--surface);
}

.contact-layout {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  gap: clamp(45px, 8vw, 110px);
  align-items: start;
}

.contact-copy {
  max-width: 460px;
}

.contact-copy h2 {
  margin-bottom: 25px;
}

.contact-copy p {
  font-size: 16px;
  line-height: 1.85;
}

.contact-details {
  display: grid;
  gap: 15px;
  margin-top: 35px;
}

.contact-link {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 15px 0;
  border-bottom: 1px solid var(--line);
  color: var(--ink);
  font-size: 14px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.contact-link:hover {
  color: var(--orange-dark);
}

.contact-link-icon {
  display: grid;
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  place-items: center;
  background: var(--forest);
  color: var(--white);
  font-size: 17px;
}

.contact-form {
  padding: clamp(28px, 5vw, 54px);
  background: var(--white);
  box-shadow: var(--shadow);
}

.contact-form h3 {
  margin-bottom: 12px;
}

.form-intro {
  margin-bottom: 30px;
  font-size: 14px;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 51px;
  padding: 13px 15px;
  border: 1px solid #d5d7d1;
  border-radius: 2px;
  background: var(--paper);
  color: var(--ink);
  font-size: 14px;
}

.form-field textarea {
  min-height: 135px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #737b77;
  opacity: 1;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--orange);
  outline: 2px solid rgba(189, 101, 61, .18);
  outline-offset: 1px;
}

.form-submit {
  width: 100%;
  margin-top: 24px;
}

.form-note {
  margin: 14px 0 0;
  color: #737b77;
  font-size: 11px;
  line-height: 1.6;
}

/* FOOTER */
.site-footer {
  padding: 58px 0 25px;
  background: var(--forest-deep);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 50px;
  padding-bottom: 45px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-description {
  color: rgba(255, 255, 255, .65);
}

.footer-summary {
  max-width: 380px;
  margin-top: 18px;
  color: rgba(255, 255, 255, .72);
  font-size: 13px;
}

.footer-contact {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
}

.footer-contact a {
  color: var(--white);
  font-size: 14px;
  font-weight: 700;
}

.footer-contact a:hover {
  color: var(--orange-light);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, .2);
  color: rgba(255, 255, 255, .58);
  font-size: 11px;
}

/* ACCESSIBLE MOBILE MENU CONTROL */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: var(--white);
  color: var(--ink);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* RESPONSIVE: MEDIUM SCREENS */
@media (max-width: 900px) {
  :root {
    --gutter: clamp(22px, 5vw, 42px);
    --section-space: 82px;
  }

  .header-inner {
    min-height: 76px;
  }

  .brand-logo {
    width: 54px;
    height: 54px;
  }

  .main-nav {
    gap: 15px;
  }

  .main-nav a:not(.button) {
    font-size: 11px;
  }

  .main-nav .button {
    min-height: 46px;
    padding: 12px 16px;
    font-size: 10px;
  }

  .hero {
    min-height: 650px;
  }

  .intro-layout,
  .why-layout,
  .approach-layout {
    grid-template-columns: 1fr 1fr;
    gap: 42px;
  }

  .intro-visual img {
    height: 390px;
  }

  .projects-grid {
    grid-template-rows: 260px 220px;
  }

  .contact-layout {
    gap: 38px;
  }
}

/* RESPONSIVE: MOBILE NAVIGATION */
@media (max-width: 700px) {
  :root {
    --gutter: 22px;
    --section-space: 72px;
  }

  html {
    scroll-padding-top: 76px;
  }

  .header-inner {
    position: relative;
    min-height: 74px;
    gap: 12px;
  }

  .brand {
    gap: 10px;
  }

  .brand-logo {
    width: 47px;
    height: 47px;
  }

  .brand-name {
    font-size: 18px;
  }

  .brand-description {
    font-size: 8px;
  }

  .menu-toggle {
    display: flex;
  }

  .main-nav {
    display: none;
    position: absolute;
    z-index: 30;
    top: 100%;
    right: calc(var(--gutter) * -1);
    left: calc(var(--gutter) * -1);
    max-height: calc(100svh - 74px);
    overflow-y: auto;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 0;
    padding: 12px var(--gutter) 22px;
    border-top: 1px solid var(--line);
    background: var(--white);
    box-shadow: 0 14px 25px rgba(25, 35, 31, .12);
  }

  .main-nav.is-open {
    display: flex;
  }

  .main-nav a:not(.button) {
    display: block;
    width: 100%;
    padding: 14px 0;
    border-bottom: 1px solid var(--line);
    font-size: 13px;
  }

  .main-nav a:not(.button)::after {
    display: none;
  }

  .main-nav .button {
    width: 100%;
    margin-top: 14px;
  }

  .hero {
    min-height: 670px;
    min-height: min(740px, calc(100svh - 74px));
    align-items: flex-end;
  }

  .hero::before {
    background:
      linear-gradient(0deg, rgba(21, 32, 29, .94) 0%, rgba(21, 32, 29, .78) 48%, rgba(21, 32, 29, .12) 100%);
  }

  .hero-media {
    object-position: 58% center;
  }

  .hero-content {
    padding-block: 95px 64px;
  }

  h1 {
    font-size: clamp(49px, 12vw, 72px);
  }

  h2 {
    font-size: clamp(40px, 10vw, 54px);
  }

  .hero-description {
    max-width: 480px;
    font-size: 16px;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
    max-width: 360px;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-note {
    margin-top: 30px;
    font-size: 10px;
  }

  .intro-layout,
  .why-layout,
  .approach-layout,
  .contact-layout {
